draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 80);
  ctx.stroke();

  // three good things
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('1', W/2 - 50 + 20*Math.cos(t), H/2 - 100 + 20*Math.sin(t));
  ctx.fillText('2', W/2 + 20*Math.cos(t), H/2 - 100 + 20*Math.sin(t));
  ctx.fillText('3', W/2 + 20*Math.cos(2*t), H/2 - 50 + 20*Math.sin(2*t));

  // thought bubble
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 120 + 10*Math.sin(t), 30, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 90 + 10*Math.sin(t));
  ctx.lineTo(W/2, H/2 - 120 + 10*Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
